{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Creating a secure API is crucial when building modern web applications, especially when handling sensitive user information. In this blog post, we’ll walk through setting up protected routes in Node.js and Express API using middleware for authentication and authorization. We’ll employ HTTP-only cookies to securely store JWTs (JSON Web Tokens), check cookie validity with middleware, and enforce role-based access control (RBAC).","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":2,"mode":"normal","style":"","text":"For readers interested in learning why HTTP-only cookies are a secure choice for storing JWTs, check out my previous blog (link here).","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"bookmark","version":1,"url":"__GHOST_URL__/best-practices-for-securing-jwt-tokens-a-comprehensive-guide/","metadata":{"icon":"https://s3-eu-north-1.amazonaws.com/agile-coder-bucket/2024/08/logo-removebg-preview.png","title":"Best Practices for Securing JWT Tokens: A Comprehensive Guide","description":"JWTs enable stateless authentication, but securing them is critical. Avoid storing tokens in local storage due to XSS risks. Instead, use HttpOnly, Secure cookies to prevent access via JavaScript and limit CSRF attacks. Pair short-lived access tokens with refresh tokens for enhanced security.","author":"Smruti Ranjan Badatya","publisher":"Agile Coder","thumbnail":"https://s3-eu-north-1.amazonaws.com/agile-coder-bucket/2024/10/secure-storage-for-jwt.png"},"caption":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Why Use Protected Routes?","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Protected routes help secure parts of your application by ensuring that only authenticated and, in some cases, authorized users can access them. This is particularly valuable for APIs, as it helps prevent unauthorized access to sensitive data. With Express, we can easily set up middleware functions to authenticate users and restrict access to specific routes.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Setting Up the Authorize Middleware","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The first middleware we’ll implement is ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"authorize","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", which verifies if a user is authenticated. This middleware will:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Check for an access token (JWT) in the HTTP-only cookie for web clients.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Verify the token using ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"jwt.verify","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":".","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":2},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Ensure that the device making the request is trusted by cross-referencing the device information stored in the database.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":3}],"direction":"ltr","format":"","indent":0,"type":"list","version":1,"listType":"bullet","start":1,"tag":"ul"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Here’s the ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"authorize","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" middleware:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"import { Request, Response, NextFunction } from "express";
import jwt from "jsonwebtoken";
import { ExtendedRequest } from "../domains/user/types";

export const authorize = (req: Request, res: Response, next: NextFunction) => {
  try {
    let accessToken = req.cookies?.accessToken;

    if (!accessToken) {
      return res.status(401).json({ error: "Access token not provided" });
    }

    // Verify JWT
    jwt.verify(
      accessToken,
      process.env.SECRET_KEY || "",
      async (err: any, decoded: any) => {
        if (err) {
          return res.status(403).json({ error: "Invalid access token" });
        }

        // Attach decoded user data to request
        (req as ExtendedRequest).user = decoded;
        next();
      }
    );
  } catch (error) {
    console.error("Error in authorize middleware:", error);
    res.status(500).json({ error: "Internal server error" });
  }
};","language":"TypeScript","caption":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Key Points of the ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"authorize","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" Middleware","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Token Retrieval:","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" For web clients, we retrieve the JWT from an HTTP-only cookie; ","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"JWT Verification:","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" Using this","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"jwt.verify","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", we check if the token is valid and hasn’t expired.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":2}],"direction":"ltr","format":"","indent":0,"type":"list","version":1,"listType":"bullet","start":1,"tag":"ul"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Enforcing Role-Based Access Control (RBAC)","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"For certain API endpoints, only specific users (like admins) should be allowed access. We can implement this with another middleware function, ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"allowAdminsOnly","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", which checks if the user has the correct role to access the route.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Here’s the ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"allowAdminsOnly","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" middleware:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"import { Request, Response, NextFunction } from "express";
import { ExtendedRequest } from "../domains/user/types";
import { userTypes } from "../utils/constants";

export const allowAdminsOnly = (
  req: Request,
