GMAIL_APP_PASSWORD=your-app-password
NODE_ENV=development","language":"plaintext","caption":""},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Note","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": You should use an ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"App Password","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" generated from your Gmail account for secure authentication. Standard passwords won’t work with Gmail if 2FA is enabled.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-quote","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"I always use a particular directory structure for most of the medium-sized node projects. I have talked about this in the article below:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"bookmark","version":1,"url":"__GHOST_URL__/scalable-directory-structure-for-nodejs-express-web-servers/","metadata":{"icon":"https://s3-eu-north-1.amazonaws.com/agile-coder-bucket/2024/08/logo-removebg-preview.png","title":"Scalable Directory Structure for NodeJS + Express Web Servers","description":"This blog explores a scalable folder structure for Node.js Express servers using Docker, TypeScript, and domain-driven design. Learn how to organize key components like configurations, domains, middlewares, and utilities to ensure maintainability, modularity, and scalability in your application.","author":"Smruti Ranjan Badatya","publisher":"Agile Coder","thumbnail":"https://s3-eu-north-1.amazonaws.com/agile-coder-bucket/2024/09/scalable-directory-structure.png"},"caption":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"For the nodemailer setup, here is what I do","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"📂 project-root
