 ┣ 📜 package.json                    # Project metadata and dependencies
 ┣ 📜 README.md                       # Project documentation
 ┗ 📜 .gitignore                      # Ignoring files like .env","language":"","caption":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"3. Nodemailer Configuration","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"We’ll use this configuration to define the email service and authentication credentials for Nodemailer. This is done by loading values from your ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":".env","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" file using ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"dotenv","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":".","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"// configs/nodemailer.js
import dotenv from "dotenv";
dotenv.config();

export const nodemailerConfig = {
