  },
};
","language":"javascript","caption":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"This config enables you to use Gmail’s SMTP server with SSL for secure email sending. You can easily replace the ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"service","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" and ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"auth","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" fields for other SMTP servers (like Outlook or SendGrid).","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Creating the Email Transporter","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Next, let's create a ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"transporter","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" that will use the SMTP configuration to send emails. This transporter is responsible for delivering emails via the specified SMTP server.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"// services/emailService.js
import dotenv from "dotenv";
import nodemailer from "nodemailer";
import { nodemailerConfig } from "../../configs/nodemailer";

dotenv.config();

// Create a Nodemailer transporter using the configuration
const transporter = nodemailer.createTransport(nodemailerConfig);

// Verify the transporter connection
export const checkTransporterStatus = () => {
  transporter.verify(function (error, success) {
    if (error) {
      console.error("Error verifying transporter:", error);
    } else {
      console.log("Server is ready to take our messages");
    }
  });
};
","language":"javascript","caption":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"By using the ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"verify","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" method, we ensure the SMTP server connection is ready before attempting to send emails. Running this function will help catch any potential configuration issues early on.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Sending Verification Emails with Nodemailer","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"In many applications, you’ll want to send ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"verification emails","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" for user sign-up or ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"password reset emails","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":". Here’s a function that sends different types of emails, based on templates for each case.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"1. Organizing Email Templates","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"We'll use HTML templates to format our emails. The templates will be dynamically updated with values like OTP and username before sending.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"// services/emailService.js

import fs from "fs";
import path from "path";
import { verificationTypes } from "../../utils/verificationTypes";

// Function to get the email template path
const getTemplatePath = (templateName) => {
  const projectRoot = process.cwd();
  const isProduction = process.env.NODE_ENV === "production";

  const templatesDir = isProduction
    ? path.join(projectRoot, "dist", "templates")
    : path.join(projectRoot, "src", "templates");

  return path.join(templatesDir, templateName);
};

// Function to send verification or password reset emails
export const sendVerificationEmail = (
  emailAddress,
  otp,
  type,
  username = "User"
) => {
  return new Promise((resolve, reject) => {
    if (!emailAddress) {
      reject("Email address is undefined or null");
      return;
    }

    // Set the appropriate email template and subject
    let mailTemplatePath = getTemplatePath("email_verification_template.html");

    let mailSubject = "OTP for Email Verification";

    if (type === verificationTypes.password_reset) {
      mailTemplatePath = getTemplatePath("password_reset_template.html");
      mailSubject = "OTP for Password Reset";
    }

    // Read and update the template with the dynamic values
    fs.readFile(mailTemplatePath, { encoding: "utf-8" }, (err, data) => {
      if (err) {
        console.error("Error reading email template:", err);
        reject("Failed to load email template");
        return;
      }

      // Replace placeholders in the template with real values
      const html = data
        .replace("{{otp}}", otp)
        .replace("{{username}}", username);

      // Set up the email options
      const mailOptions = {
        from: process.env.GMAIL_CLIENT_ID || "",
        to: emailAddress,
        subject: mailSubject,
        html: html,
      };

      // Send the email
      transporter.sendMail(mailOptions, (error, info) => {
        if (error) {
          console.error("Error sending email:", error);
          reject("Failed to send email");
          return;
        }
        console.log("Email sent:", info.response);
        resolve(info.response);
      });
    });
  });
};
