y storing JWT tokens:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"sessionStorage.getItem("token");","language":"javascript","caption":""},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Recommendation","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": While Session Storage is more secure than Local Storage in some cases, avoid using it for sensitive JWTs unless you are confident in your XSS protections.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"3. Cookies","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Cookies are a popular choice for storing JWT tokens. They have specific flags that improve security:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"HttpOnly Flag","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"HttpOnly","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" cookies cannot be accessed by JavaScript, which protects them from XSS attacks. If you set the ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"HttpOnly","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" flag to ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"true","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", the cookie is only accessible via HTTP requests.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Pros","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": It protects the token from XSS attacks since JavaScript cannot retrieve it.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":2},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Cons","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": While ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"HttpOnly","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" cookies protect token confidentiality, they are still vulnerable to ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"CSRF attacks","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":". Attackers can exploit CSRF vulnerabilities to send unauthorized requests using a valid JWT without the user's knowledge.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":3}],"direction":"ltr","format":"","indent":0,"type":"list","version":1,"listType":"bullet","start":1,"tag":"ul"},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"HttpOnly: false","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h4"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Cookies with ","type":"extended-text","version":1},{"detail":0,"format":16,"mode":"normal","style":"","text":"HttpOnly: false","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" can be accessed via JavaScript, making them vulnerable to XSS attacks. Here's how an attacker could retrieve such a token:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"codeblock","version":1,"code":"document.cookie.split('; ').find(
