n":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h4"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"Secure","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" flag ensures cookies are only sent over HTTPS, preventing them from being exposed via unsecured HTTP connections.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Best Practice for Cookies","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":":","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"HttpOnly: true","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Secure: true","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" (use HTTPS)","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":2},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"SameSite: lax or strict","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" (depending on your application's needs)","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":3}],"direction":"ltr","format":"","indent":0,"type":"list","version":1,"listType":"bullet","start":1,"tag":"ul"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"4. In-memory Storage","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Pros","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Storing JWTs in memory is the most secure option in terms of exposure to attacks like XSS, as tokens are not persisted in the browser. Once the page is refreshed or the session ends, the token is gone.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Cons","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Since tokens are stored in memory, they are lost if the user refreshes the page or navigates away from the site, which might impact the user experience.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Web Workers","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" for Enhanced Security","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h4"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"A more secure in-memory storage solution involves using ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"Web Workers","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":". Web Workers run in a background thread and communicate with the main thread via ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"MessageChannels","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":". Secrets stored in a Web Worker are not directly accessible to the browser’s main JavaScript context, mitigating XSS risks.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"However, like ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"HttpOnly","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" cookies, an attacker could use XSS to send messages to the Web Worker, indirectly using the secret.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Recommendation","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": When possible, store JWT tokens in Web Workers to isolate secrets from the main application and minimize XSS risks.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Implementing a Secure JWT Flow","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"To maximize security, it’s recommended to use ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"two tokens","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":":","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Access Token","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Short-lived token for accessing resources.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Refresh Token","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Long-lived token used to renew the access token when it expires.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":2}],"direction":"ltr","format":"","indent":0,"type":"list","version":1,"listType":"bullet","start":1,"tag":"ul"},{"type":"codeblock","version":1,"code":"res.cookie("accessToken", accessToken, {
  secure: true,
  httpOnly: true,
  sameSite: "none",
  priority: "high",
});

res.cookie("refreshToken", refreshToken, {
  secure: true,
  httpOnly: true,
  sameSite: "none",
  priority: "high",
});","language":"javascript","caption":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Best Practices:","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h4"},{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Store JWT in HttpOnly Cookies","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": The access token should be stored in a secure, HttpOnly cookie. This ensures that the token cannot be accessed via JavaScript, protecting it from XSS attacks.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Use Refresh Tokens","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Implement a short-lived access token and a long-lived refresh token. When the access token expires, the refresh token should be used to request a new one. This minimizes the window of opportunity for attackers to exploit compromised tokens.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":2},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Short Expiry Times","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Tokens should have short expiry times to limit the damage if they are stolen. After expiry, use the refresh token to obtain a new access token.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":3},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Use HTTPS","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Always transmit tokens over HTTPS to prevent them from being exposed to man-in-the-middle (MITM) attacks.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":4},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"CSRF Mitigation","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Along with HttpOnly cookies, implement additional measures to mitigate CSRF attacks, such as ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"CSRF tokens","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" or the ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"SameSite","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" attribute in cookies.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":5}],"direction":"ltr","format":"","indent":0,"type":"list","version":1,"listType":"number","start":1,"tag":"ol"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Securing JWT tokens is a vital part of ensuring your web application’s integrity and protecting user data. By choosing the right storage mechanism and following best practices like using ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"HttpOnly cookies","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"refresh tokens","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", and implementing ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"short expiry times","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":", you can significantly reduce the risks posed by XSS and CSRF attacks.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Remember, security is a moving target, and regularly revisiting your JWT storage strategies is essential as threats evolve.","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"That's it for today! See ya 👋","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"paragraph","version":1},{"type":"horizontalrule","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"References","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"OAuth 2.0 Auth Framework","type":"extended-text","version":1},{"type":"linebreak","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"https://www.rfc-editor.org/rfc/pdfrfc/rfc6749.txt.pdf","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"link","version":1,"rel":null,"target":null,"title":null,"url":"https://www.rfc-editor.org/rfc/pdfrfc/rfc6749.txt.pdf"}],"direction":"ltr","format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Secure Storage","type":"extended-text","version":1},{"type":"linebreak","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"https://auth0.com/blog/secure-browser-storage-the-facts/","type":"extended-text","version":1}],"direction":"ltr","format":"","indent":0,"type":"link","version":1,"rel":null,"target":null,"title":null,"url":"https://auth0.com/blog/secu